-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
-- P99 requires three scales only; the optional net/idol is not an additional payment prerequisite.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Leave me alone, beast! Or I will cut your belly open and feed your entrails to the sharks.")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 25107 }) then
    e.self:Say("So you are the servant of Wenglawks here to retrieve the cloak. I will need more scales to make the cloak in his size. I have already slaughtered a good thirty sirens and the cloak is nearly complete. Go forth and slaughter my kind and bring me the finest scales you can find. Let this idol be your protection from the wrath of E'ci. I will continue my work on the cloak.")
    e.other:AddEXP(1000)
    e.other:SummonItem(25108)
  elseif item_lib.check_turn_in(e.trade, { item1 = 25109, item2 = 25109, item3 = 25109 }) then
    e.self:Say("You are an excellent hunter. Tell me, did you enjoy the screams of the sirens as they perished? I find the sound so wonderful.")
    e.self:Emote("hands you a gigantic cloak made of slick siren scales.")
    e.self:Say("I was done making the cloak already. I just wanted to watch you slay the weak. I thank you for bringing more suffering into the world.")
    e.other:SummonItem(25110)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
